import 'package:aivexus_temperature_units/temperature_units.dart';
void expectNear(double actual, double expected) {
  if ((actual - expected).abs() > 1e-9) throw StateError('expected $expected but got $actual');
}
void main() {
  expectNear(celsiusToFahrenheit(0.0), 32.0);
  expectNear(celsiusToFahrenheit(100.0), 212.0);
  expectNear(celsiusToFahrenheit(-40.0), -40.0);
  expectNear(fahrenheitToCelsius(32.0), 0.0);
  expectNear(fahrenheitToCelsius(212.0), 100.0);
  expectNear(fahrenheitToCelsius(-40.0), -40.0);
  expectNear(fahrenheitToCelsius(celsiusToFahrenheit(37.5)), 37.5);
  print('PASS: independently consumed Qwen-generated temperature conversion module');
}

import 'package:aivexus_delta_codec/delta_codec.dart';
void main() {
  final samples = <int>[12, -4, -4, 9, 0];
  final original = List<int>.from(samples);
  final encoded = encodeDeltas(samples);
  if (encoded.toString() != '[12, -16, 0, 13, -9]') throw StateError('encoding failed: $encoded');
  if (decodeDeltas(encoded).toString() != samples.toString()) throw StateError('decoding failed');
  if (samples.toString() != original.toString()) throw StateError('input mutated');
  if (encodeDeltas(<int>[]).isNotEmpty || decodeDeltas(<int>[]).isNotEmpty) throw StateError('empty input failed');
  print('PASS: independently consumed LLM-generated delta module');
}
